const decryptedPayload = $json.decryptedPayload;

if (typeof decryptedPayload !== "string" || !decryptedPayload.trim()) {
  throw new Error("Decrypted payload is missing.");
}

let payload;
try {
  payload = JSON.parse(decryptedPayload);
} catch (error) {
  throw new Error(`Unable to parse decrypted WhatsApp Flow payload: ${error.message}`);
}

if (!payload.screen) {
  throw new Error("The decrypted payload does not contain a screen value.");
}

return [{
  json: {
    screen: payload.screen,
    flow_token: payload.flow_token ?? "",
    date: payload.data?.date ?? null,
    data: payload.data ?? {},
    decryptedPayload
  }
}];

const data = $json.data ?? {};
const appointmentRows =
  (Array.isArray(data.appointments) && data.appointments) ||
  (Array.isArray(data.available_appointments) && data.available_appointments) ||
  (Array.isArray(data.slots) && data.slots) ||
  (Array.isArray(data) && data) ||
  [];

const grouped = {};

for (const appointment of appointmentRows) {
  const dateValue = appointment.appointment_date ?? appointment.date;
  const timeValue = appointment.start_time ?? appointment.time;

  if (!dateValue || !timeValue) continue;

  const date = String(dateValue).slice(0, 10);
  if (!grouped[date]) grouped[date] = [];
  grouped[date].push(String(timeValue));
}

if (Object.keys(grouped).length === 0 && data.date && Array.isArray(data.start_times)) {
  grouped[String(data.date).slice(0, 10)] = data.start_times.map(String);
}

const selectedDate = data.date ? String(data.date).slice(0, 10) : Object.keys(grouped)[0] ?? "";
const startTimes = selectedDate ? (grouped[selectedDate] ?? []) : [];

return [{
  json: {
    appointment_date: selectedDate,
    start_times: startTimes
  }
}];

const data = $json.data ?? {};
const seats = data.seats;

if (!Array.isArray(seats)) {
  throw new Error("The DATE_SELECTION_SCREEN payload must contain a data.seats array.");
}

return [{
  json: {
    seats: seats.map(seat => String(seat))
  }
}];

const body = $json.body ?? $json;

const encryptedFlowData = body.encrypted_flow_data;
const encryptedAesKey = body.encrypted_aes_key;
const initialVector = body.initial_vector;

if (!encryptedFlowData || !encryptedAesKey || !initialVector) {
  throw new Error("Webhook payload must include encrypted_flow_data, encrypted_aes_key, and initial_vector.");
}

return [{
  json: {
    encryptedFlowData: Buffer.from(encryptedFlowData, "base64"),
    encryptedAesKey: Buffer.from(encryptedAesKey, "base64"),
    initialVector: Buffer.from(initialVector, "base64")
  }
}];

const crypto = require("crypto");

const privateKey = `-----BEGIN PRIVATE KEY-----
[INSERT YOUR PRIVATE KEY HERE]
-----END PRIVATE KEY-----`;

function toBuffer(value) {
  if (Buffer.isBuffer(value)) return value;
  if (value?.type === "Buffer" && Array.isArray(value.data)) return Buffer.from(value.data);
  if (Array.isArray(value)) return Buffer.from(value);
  if (typeof value === "string") return Buffer.from(value, "base64");
  throw new Error("Invalid binary input.");
}

const input = $input.first().json;
const encryptedAesKey = toBuffer(input.encryptedAesKey);
const initialVector = toBuffer(input.initialVector);
const encryptedFlowData = toBuffer(input.encryptedFlowData);

if (initialVector.length !== 16) {
  throw new Error("Invalid initialization vector. Expected 16 bytes.");
}

const aesKey = crypto.privateDecrypt(
  {
    key: privateKey,
    padding: crypto.constants.RSA_PKCS1_OAEP_PADDING,
    oaepHash: "sha256"
  },
  encryptedAesKey
);

if (aesKey.length !== 16) {
  throw new Error(`Invalid AES key length: expected 16 bytes, received ${aesKey.length}.`);
}

if (encryptedFlowData.length <= 16) {
  throw new Error("Encrypted flow data is too short.");
}

const authTag = encryptedFlowData.subarray(-16);
const encryptedData = encryptedFlowData.subarray(0, -16);
const decipher = crypto.createDecipheriv("aes-128-gcm", aesKey, initialVector);
decipher.setAuthTag(authTag);

const decryptedPayload = Buffer.concat([
  decipher.update(encryptedData),
  decipher.final()
]).toString("utf8");

return [{
  json: {
    decryptedPayload,
    aesKey: aesKey.toString("base64"),
    initialVector: initialVector.toString("base64")
  }
}];

const crypto = require("crypto");

function toBuffer(value) {
  if (Buffer.isBuffer(value)) return value;
  if (value?.type === "Buffer" && Array.isArray(value.data)) return Buffer.from(value.data);
  if (Array.isArray(value)) return Buffer.from(value);
  if (typeof value === "string") return Buffer.from(value, "base64");
  throw new Error("Invalid binary value.");
}

const initialVector = toBuffer($("move to base64").first().json.initialVector);
const aesKey = Buffer.from($("Decryption Code").first().json.aesKey, "base64");
const flowToken = $("Json Parser").first().json.flow_token;

if (initialVector.length !== 16) throw new Error("Invalid initialization vector.");
if (aesKey.length !== 16) throw new Error("Invalid AES key.");
if (!flowToken) throw new Error("Flow token is missing.");

const appointmentItems = $input.all().map(item => item.json);
const date = appointmentItems[0]?.appointment_date ?? $("Json Parser").first().json.date ?? "";
const startTimes = appointmentItems.flatMap(item => item.start_times ?? []);

const responseData = {
  status: "active",
  time: startTimes.map((time, index) => ({
    id: `time_${index + 1}`,
    title: String(time)
  })),
  date: date ? [{ id: "date_1", title: String(date) }] : []
};

const responseMessage = JSON.stringify({
  version: "3.0",
  action: "data_exchange",
  screen: "APPOINTMENT",
  data: responseData,
  flow_token: flowToken
});

const invertedIV = Buffer.from(initialVector.map(byte => (~byte) & 0xff));
const cipher = crypto.createCipheriv("aes-128-gcm", aesKey, invertedIV);
const encrypted = Buffer.concat([cipher.update(responseMessage, "utf8"), cipher.final()]);
const result = Buffer.concat([encrypted, cipher.getAuthTag()]);

return [{ json: { body: result.toString("base64") } }];

